import json
d=json.load(open('.omgithub/conversation.json'))
msgs=d['messages']
print(len(msgs))
for m in msgs[-8:]:
    print('---', m.get('info',{}).get('role'), m.get('info',{}).get('time'))
    parts=m.get('parts',[])
    for p in parts:
        t=p.get('type')
        if t=='text': print(p.get('text','')[:2000])
        elif t=='tool': print('TOOL',p.get('tool'), str(p.get('state',{}).get('input',''))[:500])
        else: print(t, str(p)[:300])
EOF

