function completeContract() {
  if (missionDone) return;
  missionDone = true;
  const isFinal = job >= TOTAL_JOBS && !campaignComplete;
  const reward = 1200 + job * 300 + (isFinal ? 1500 : 0), xp = 110 + job * 20;
  addCash(reward); gainXP(xp); player.heat = Math.min(10, player.heat + 1);
  burst(player.x, 1.2, player.z, '#66f0c2', 28, 7); sfx.win();
  if (isFinal) {
    campaignComplete = true;
    showToast('FINAL CONTRACT COMPLETE · +$' + reward.toLocaleString() + ' · THE NIGHT IS YOURS', 'good');
    setTimeout(() => { if (playing && !finalWinOpen) showWinScreen(); }, 1500);
    return;
  }
  showToast('JOB COMPLETE · +$' + reward.toLocaleString() + ' · +' + xp + ' XP', 'good');
  setTimeout(() => {
    if (!playing || campaignComplete) return;
    job++; startContract(false); showToast('NEW CONTRACT · JOB ' + String(job).padStart(2, '0') + ' / ' + String(TOTAL_JOBS).padStart(2, '0'), 'good');
  }, 5200);
}
function showWinScreen() {
  if (finalWinOpen) return;
  finalWinOpen = true; winCamT = 0;
  mouse.down = false; touch.fire = false; touch.boost = false; touch.move.active = false;
  if (document.pointerLockElement) document.exitPointerLock();
  const seconds = Math.max(1, Math.round((performance.now() - runStart) / 1000));
  const mins = Math.floor(seconds / 60), secs = seconds % 60;
  el.winStats.innerHTML = `
    <div class="win-stat"><b>$${player.cash.toLocaleString()}</b><span>CREDITS EARNED</span></div>
    <div class="win-stat"><b>${player.kills}</b><span>BOUNTIES DOWN</span></div>
    <div class="win-stat"><b>${player.level}</b><span>STREET RANK</span></div>
    <div class="win-stat"><b>${mins}:${String(secs).padStart(2, '0')}</b><span>RUN TIME</span></div>`;
  el.win.classList.add('open');
  el.crosshair.classList.remove('on');
  el.prompt.classList.remove('on');
}
function freeRoam() {
  el.win.classList.remove('open'); finalWinOpen = false;
  job++; startContract(false);
  showToast('FREE ROAM · CONTRACT ' + String(job).padStart(2, '0') + ' INBOUND', 'good');
  lockPointer();
}
document.querySelector('#win-again').addEventListener('click', () => location.reload());
document.querySelector('#win-roam').addEventListener('click', freeRoam);

