Good. Event progress for checkpoint says "M TO DROP" but should "M TO EXIT" for checkpoint. Adjust later perhaps use `streetEvent.type === 'checkpoint' ? 'M TO EXIT' : 'M TO DROP'`. Fine.

Now implement spawn/complete/fail/update functions. Where to place? Near `completeContract` / street ops. Could place after `freeRoam` before doors. Need functions use `enemies`, `markEnemy`, `clearEnemyMarks`. We'll define helper functions for marks near event functions. `enemies` is defined after (line ~500) but function bodies executed later, fine. `streetBeacon` and `streetEvent` initialized before. We'll place after `freeRoam` and before doors. But `freeRoam` sets eventCooldown; we need update freeRoam to `eventCooldown = 6;` and maybe cleanup previous event. Add later.

Function definitions:

```
function clearEnemyMarks() { for (const e of enemies) e.marker.visible=false; }
function markEnemy(e) { e.marker.visible = true; e.alert = Math.max(e.alert, 5); }
function pickEventSpot() { const pool = EVENT_SPOTS.filter(s => dist2(player.x, player.z, s.x, s.z) > 45); const list = pool.length ? pool : EVENT_SPOTS; const s=list[Math.floor(Math.random()*list.length)]; return s; }
function spawnStreetEvent() {
 if (streetEvent.active || !campaignComplete) return;
 const alive = enemies.filter(e=>!e.dead);
 let types = ['drop','checkpoint']; if (alive.length >=1) types.push('bounty'); if (alive.length >=3) types.push('takedown');
 const type = types[Math.floor(Math.random()*types.length)];
 streetEvent.active=true; streetEvent.type=type; streetEvent.progress=0; streetEvent.target=null; streetEvent.targets=[];
 streetBeacon.visible=false; clearEnemyMarks();
 const scale = 1 + job * .08; // maybe use job
 if (type === 'bounty') {
   const distant = alive.filter(e => dist2(player.x,player.z,e.x,e.z) > 35);
   const pool = distant.length?distant:alive;
   const target=pool[Math.floor(Math.random()*pool.length)];
   streetEvent.target=target; streetEvent.x=target.x; streetEvent.z=target.z; streetEvent.goal=1;
   streetEvent.name='BOUNTY MARK'; streetEvent.copy='A marked runner is loose in the district. Take them down before the clock runs out.';
   streetEvent.reward=500+job*45; streetEvent.xp=55+job*6; streetEvent.duration=100; streetEvent.timer=100;
   markEnemy(target);
 } else if (type === 'takedown') {
   const pool = alive.filter(...>30).sort(()=>Math.random()-.5);
   const chosen = (pool.length>=3?pool:alive.slice()).slice(0,3);
   streetEvent.targets=chosen; chosen.forEach(markEnemy);
   streetEvent.goal=3; streetEvent.name='SHAKEDOWN'; streetEvent.copy='Three marked runners are working this block. Drop all three before they scatter.';
   streetEvent.reward=800+job*55; streetEvent.xp=90+job*8; streetEvent.duration=120; streetEvent.timer=120;
 } else if (type === 'drop') {
   const spot=pickEventSpot(); ...
   streetEvent.name='DEAD DROP'; copy='A supply cache is exposed...'; reward=420+job*35; xp=50+job*6; duration=75;
   streetBeacon.position.set(x,0,z); streetBeacon.visible=true;
 } else { checkpoint; reward... duration 60; name='EXTRACTION WINDOW'; copy='A clean exit...' }
 showToast('STREET OP · '+name, 'good'); sfx.pickup(); updateHUD(true);
}
```

Note for takedown `alive.slice()` order fixed but okay. `pool` sorted random. If pool length <3, use alive sorted random maybe. use `const source = (pool.length>=3?pool:alive.slice().sort(...)); chosen=source.slice(0,3)`. Fine.

Potential enemy chosen far but near? fine.

`completeStreetEvent(reason)`:
```
function completeStreetEvent() {
 const ev=streetEvent; if(!ev.active) return;
 const x = ev.target ? ev.target.x : ev.x;
 const z = ev.target ? ev.target.z : ev.z;
 addCash(ev.reward); gainXP(ev.xp);
 burst(x,1.2,z,'#ffc35e',24,7); sfx.win();
 showToast('STREET OP COMPLETE · +$'+reward.toLocaleString()+' · +'+xp+' XP','good');
 streetBeacon.visible=false; clearEnemyMarks();
 streetEvent.active=false;
 eventCooldown = 26 + Math.random()*20;
 updateHUD(true);
}
```
Should not call `updateHUD(true)` before active false? We set active false then update, good.

`failStreetEvent()`:
```
const ev=streetEvent; if !active return; showToast('STREET OP EXPIRED · '+ev.name,'bad'); sfx.deny(); ...
eventCooldown=18+Math.random()*14;
```

`updateStreetEvents(dt)`:
