function freeRoam() {
  el.win.classList.remove('open'); finalWinOpen = false;
  job++; startContract(false);
  streetEvent.active = false; streetBeacon.visible = false; clearEnemyMarks();
  eventCooldown = 7;
  showToast('FREE ROAM · CONTRACT ' + String(job).padStart(2, '0') + ' INBOUND · WATCH FOR STREET OPS', 'good');
  lockPointer();
}
document.querySelector('#win-again').addEventListener('click', () => location.reload());
document.querySelector('#win-roam').addEventListener('click', freeRoam);

/* ---------- street ops ---------- */
function clearEnemyMarks() { for (const e of enemies) if (e.marker) e.marker.visible = false; }
function markEnemy(e) { e.marker.visible = true; e.alert = Math.max(e.alert, 5); }
function pickEventSpot() {
  const pool = EVENT_SPOTS.filter(s => !blockedAt(s.x, s.z, .4) && dist2(player.x, player.z, s.x, s.z) > 46);
  const list = pool.length ? pool : EVENT_SPOTS;
  return list[Math.floor(Math.random() * list.length)];
}
function spawnStreetEvent() {
  if (streetEvent.active || !campaignComplete || mode === 'interior' || shopOpen) return;
  const alive = enemies.filter(e => !e.dead);
  const types = ['drop', 'checkpoint'];
  if (alive.length >= 1) types.push('bounty');
  if (alive.length >= 3) types.push('takedown');
  const type = types[Math.floor(Math.random() * types.length)];
  const ev = streetEvent;
  ev.active = true; ev.type = type; ev.progress = 0; ev.target = null; ev.targets = [];
  streetBeacon.visible = false; clearEnemyMarks();
  if (type === 'bounty') {
    const far = alive.filter(e => dist2(player.x, player.z, e.x, e.z) > 36);
    const pool = far.length ? far : alive;
    const target = pool[Math.floor(Math.random() * pool.length)];
    ev.target = target; ev.x = target.x; ev.z = target.z; ev.goal = 1;
    ev.name = 'BOUNTY MARK'; ev.copy = 'A marked runner is loose in the district. Take them down before the clock runs out.';
    ev.reward = 500 + job * 45; ev.xp = 55 + job * 6; ev.duration = 100; ev.timer = 100;
    markEnemy(target);
  } else if (type === 'takedown') {
    const far = alive.filter(e => dist2(player.x, player.z, e.x, e.z) > 30).sort(() => Math.random() - .5);
    const source = far.length >= 3 ? far : alive.slice().sort(() => Math.random() - .5);
    ev.targets = source.slice(0, 3); ev.goal = 3;
    ev.targets.forEach(markEnemy);
    ev.name = 'SHAKEDOWN'; ev.copy = 'Three marked runners are working the district. Drop all three before they scatter.';
    ev.reward = 800 + job * 55; ev.xp = 90 + job * 8; ev.duration = 120; ev.timer = 120;
  } else if (type === 'drop') {
    const spot = pickEventSpot();
    ev.x = spot.x; ev.z = spot.z;
    ev.name = 'DEAD DROP'; ev.copy = 'A supply cache is exposed nearby. Grab it before the window closes.';
    ev.reward = 420 + job * 35; ev.xp = 50 + job * 6; ev.duration = 75; ev.timer = 75;
    streetBeacon.position.set(ev.x, 0, ev.z); streetBeacon.visible = true;
  } else {
    const spot = pickEventSpot();
    ev.x = spot.x; ev.z = spot.z;
    ev.name = 'EXTRACTION WINDOW'; ev.copy = 'A clean exit is open. Reach the marked point before it shuts.';
    ev.reward = 460 + job * 35; ev.xp = 55 + job * 6; ev.duration = 60; ev.timer = 60;
    streetBeacon.position.set(ev.x, 0, ev.z); streetBeacon.visible = true;
  }
  showToast('STREET OP · ' + ev.name + ' · CHECK THE MAP', 'good'); sfx.pickup();
  updateHUD(true);
}
function completeStreetEvent() {
  const ev = streetEvent; if (!ev.active) return;
  const sx = ev.target ? ev.target.x : ev.x, sz = ev.target ? ev.target.z : ev.z;
  addCash(ev.reward); gainXP(ev.xp);
  burst(sx, 1.2, sz, '#ffc35e', 24, 7); sfx.win();
  showToast('STREET OP COMPLETE · +$' + ev.reward.toLocaleString() + ' · +' + ev.xp + ' XP', 'good');
  streetBeacon.visible = false; clearEnemyMarks();
  ev.active = false; ev.target = null; ev.targets = [];
  eventCooldown = 26 + Math.random() * 20;
  updateHUD(true);
}
function failStreetEvent() {
  const ev = streetEvent; if (!ev.active) return;
  showToast('STREET OP EXPIRED · ' + ev.name, 'bad'); sfx.deny();
  streetBeacon.visible = false; clearEnemyMarks();
  ev.active = false; ev.target = null; ev.targets = [];
  eventCooldown = 18 + Math.random() * 15;
  updateHUD(true);
}
function updateStreetEvents(dt) {
  if (!campaignComplete || mode === 'interior') return;
  const ev = streetEvent;
  for (const e of enemies) {
    if (!e.marker || !e.marker.visible) continue;
    e.marker.userData.ring.rotation.z += dt * 2.2;
    const pulse = 1 + Math.sin(now * 4 + e.id) * .12;
    e.marker.userData.halo.scale.set(3 * pulse, 3 * pulse, 1);
  }
  if (!ev.active) {
    eventCooldown -= dt;
    if (eventCooldown <= 0 && !finalWinOpen) spawnStreetEvent();
    return;
  }
  ev.timer -= dt;
  if (ev.type === 'bounty' && ev.target && !ev.target.dead) { ev.x = ev.target.x; ev.z = ev.target.z; }
  if (ev.type === 'drop' || ev.type === 'checkpoint') {
    streetBeacon.userData.ring.rotation.z += dt * 1.4;
    streetBeacon.userData.ring2.rotation.z -= dt * .7;
    streetBeacon.userData.core.position.y = .85 + Math.sin(now * 2.6) * .18;
    if (dist2(player.x, player.z, ev.x, ev.z) < (ev.type === 'drop' ? 2.9 : 4.8)) { completeStreetEvent(); return; }
  }
  if (ev.timer <= 0) failStreetEvent();
}

